# Two-level category tree: sections (top level) and their subcategories.
# Slugs are generated by the model from the Russian names via transliteration.

sections = {
  "Мужское" => %w[Куртки Рубашки Брюки Свитшоты Футболки],
  "Женское" => %w[Куртки Рубашки Брюки Юбки Свитшоты],
  "Аксессуары" => %w[Сумки Головные\ уборы Ремни]
}

sections.each_with_index do |(section_name, subcategory_names), index|
  section = Category.find_or_create_by!(name: section_name, parent: nil) do |category|
    category.position = index
  end

  subcategory_names.each_with_index do |subcategory_name, subindex|
    Category.find_or_create_by!(name: subcategory_name, parent: section) do |category|
      category.position = subindex
    end
  end
end
